        function testBasePerformance(testCase)
            n = 1e5;
            data = string(rand(n,1));
            T = table(data);

            actualTiming = timeit(@() copytable(T));
            allowableTiming = 0.25; %seconds

            testCase.verifyLessThanOrEqual(actualTiming,allowableTiming)
        end

