        function testTableAllTypes(testCase)
            T = table( ...
                [pi; exp(1); pi*1000], ...                                   % double
                single([pi; exp(1); pi*1000]), ...                           % single
                half([pi; exp(1); pi*1000]), ...                             % half
                int32([42; -7; 29]), ...                               % integer
                uint64([2^40; 2^41; 2]), ...                          % unsigned integer
                half([1+2i; 3+4i; 5-6i]), ...                                  % complex half
                ["Hello"; "World"; "Again"], ...                            % string
                ['A'; 'B'; 'C'], ...                                    % char
                datetime(2025,1,1) + days([0;1;2]), ...             % datetime
                duration([1;2;3],[30;45;55],[0;0;0]), ...                % duration
                calmonths([1;2;3]), ...                             % calendar duration
                logical([1;0;1]), ...                               % logical
                {42; "test"; @sin}, ...                             % cell
                'VariableNames', { ...
                'DoubleValue', ...
                'SingleValue', ...
                'HalfValue', ...
                'Int32Value', ...
                'UInt64Value', ...
                'ComplexValue', ...
                'StringValue', ...
                'CharValue', ...
                'DateTimeValue', ...
                'DurationValue', ...
                'CalendarDurationValue', ...
                'LogicalValue', ...
                'CellValue'});

            testCase.verifyWarningFree(@() copytable(T));

            expectedLines = {strjoin(string(T.Properties.VariableNames),','),...
                "3.141592653589793,3.1415927,3.1406,42,1099511627776,1+2i,Hello,A,01-Jan-2025,01:30:00,1mo,true,42",...
                "2.718281828459045,2.7182817,2.7188,-7,2199023255552,3+4i,World,B,02-Jan-2025,02:45:00,2mo,false,test",...
                "3141.592653589793,3141.5928,3142,29,2,5-6i,Again,C,03-Jan-2025,03:55:00,3mo,true,sin"};
            actual = clipboard('paste');
            actual = strrep(actual, sprintf('\r\n'), newline);
            lines = strsplit(strtrim(actual), '\n');
            lines = cellfun(@strtrim, lines, 'UniformOutput', false);
            lines = cellfun(@string,  lines, 'UniformOutput', false);

            testCase.verifyEqual(lines, expectedLines); 
        end

        function testTableAllTypesCell(testCase)

            T = table( ...
                {pi;...                                   % double
                single(pi);...                           % single
                half(pi);...                             % half
                int32(42); ...                               % integer
                uint64(2+3i); ...                          % unsigned integer
                half(-1-2i); ...                                  % complex half
                string(missing); ...                            % string
                'A'; ...                                    % char
                datetime(2025,1,1); ...             % datetime
                duration(1,30,0); ...                % duration
                calmonths(1); ...                             % calendar duration
                true; ...                               % logical
                @(x,y)sin(x^y)}, ...                             % cell,...
                'VariableNames', "sometable");

            testCase.verifyWarningFree(@() copytable(T));

            expectedLines = [115, 111, 109, 101, 116, 97, 98, 108, 101, 10, 51,...
                46, 49, 52, 49, 53, 57, 50, 54, 53, 51, 53, 56, 57, 55, 57, 51,...
                10, 51, 46, 49, 52, 49, 53, 57, 50, 55, 10, 51, 46, 49, 52, 48,...
                54, 50, 53, 10, 52, 50, 10, 50, 43, 51, 105, 10, 45, 49, 45, 50,...
                105, 10, 10, 65, 10, 48, 49, 45, 74, 97, 110, 45, 50, 48, 50,...
                53, 10, 48, 49, 58, 51, 48, 58, 48, 48, 10, 49, 109, 111, 10,...
                116, 114, 117, 101, 10, 34, 64, 40, 120, 44, 121, 41, 115, 105,...
                110, 40, 120, 94, 121, 41, 34];
            actual = clipboard('paste');
